// Untouched original beam filter/selection/candidates on controls and real Laura.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.lang.reflect.*;import java.nio.file.*;import java.awt.geom.*;
public class LedgerBeamPurgeControlProbe extends LedgerReferenceControlProbe {
 public LedgerBeamPurgeControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 String beamRecord(Object b)throws Exception{Line2D l=(Line2D)call(b,"getMedian");Object cg=call(b,"getContextualGrade");return "{\"id\":"+call(b,"getId")+",\"kind\":"+q(b.getClass().getSimpleName())+",\"bounds\":"+rect(call(b,"getBounds"))+",\"median\":["+l.getX1()+","+l.getY1()+","+l.getX2()+","+l.getY2()+"],\"height\":"+call(b,"getHeight")+",\"grade\":"+call(b,"getGrade")+",\"contextual_grade\":"+cg+",\"removed\":false}";}
 String observe(List<Object> secs,List<Object> beams)throws Exception{
  Object sig=make("sig.SIGraph",system);setField(system,"sig",sig);for(Object b:beams)call(sig,"addVertex",b);
  Map<Object,List<Object>> map=new LinkedHashMap<>();for(Object sys:(List<?>)call(sheet,"getSystems"))map.put(sys,new ArrayList<>());map.put(system,new ArrayList<>(secs));Object filter=make("sheet.ledger.LedgersFilter",sheet);Method purge=filter.getClass().getDeclaredMethod("filterLedgerSections",Map.class);purge.setAccessible(true);purge.invoke(filter,map);List<Object> kept=map.get(system),good=new ArrayList<>();for(Object b:beams)if(b.getClass().getSimpleName().equals("BeamInter")&&(Boolean)call(b,"isGood"))good.add(b);good.sort(Comparator.comparingInt(b->{try{return ((java.awt.Rectangle)call(b,"getBounds")).x;}catch(Exception e){throw new RuntimeException(e);}}));
  Object builder=make("sheet.ledger.LedgersBuilder",system);setField(builder,"sortedSystemBeams",good);Method retrieve=builder.getClass().getDeclaredMethod("getCandidateFilaments",List.class);retrieve.setAccessible(true);List<?> candidates=(List<?>)retrieve.invoke(builder,kept);List<String> cs=new ArrayList<>(),bs=new ArrayList<>(),gs=new ArrayList<>();Object old=vertical;vertical=horizontal;try{for(Object c:candidates)cs.add(filament(c));}finally{vertical=old;}for(Object b:beams)bs.add(beamRecord(b));for(Object b:good)gs.add(beam(b));return "{\"sections\":"+StemSeedsProbe.sectionList(secs)+",\"beams\":["+String.join(",",bs)+"],\"filtered\":"+StemSeedsProbe.sectionList(kept)+",\"good_beams\":["+String.join(",",gs)+"],\"candidates\":["+String.join(",",cs)+"]}";
 }
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");Class<?> o=Class.forName("org.audiveris.omr.run.Orientation");vertical=o.getField("VERTICAL").get(null);horizontal=o.getField("HORIZONTAL").get(null);Object scale=call(sheet,"getScale");int il=(Integer)call(scale,"getInterline"),fore=(Integer)call(scale,"getFore");List<?> syslist=(List<?>)call(sheet,"getSystems");Map<Object,List<Object>> originalBeams=new LinkedHashMap<>();for(Object sys:syslist){Object sig=call(sys,"getSig");List<Object> beams=new ArrayList<>((List<?>)call(sig,"inters",Class.forName("org.audiveris.omr.sig.inter.AbstractBeamInter")));originalBeams.put(sys,beams);setField(sys,"sig",make("sig.SIGraph",sys));}Map<?,?> real=(Map<?,?>)call(make("sheet.ledger.LedgersFilter",sheet),"process");List<String> realCases=new ArrayList<>();
  for(Object sys:syslist){system=sys;List<Object> beams=originalBeams.get(sys);realCases.add("{\"system_id\":"+call(sys,"getId")+",\"observation\":"+observe(new ArrayList<>((List<?>)real.get(sys)),beams)+"}");}
  system=syslist.get(0);List<String> cases=new ArrayList<>();double good=((Number)Class.forName("org.audiveris.omr.glyph.Grades").getField("goodBeamGrade").get(null)).doubleValue();int serial=1;
  for(String kind:new String[]{"BeamInter","SmallBeamInter","BeamHookInter"})for(double grade:new double[]{Math.nextDown(good),good,Math.nextUp(good)})for(double y:new double[]{198,199,201,202})for(double slope:new double[]{0,4})for(int x:new int[]{180,216}){
   Object b=make("sig.inter."+kind,make("sig.inter.AbstractBeamInter$Impacts",1.,1.,1.,1.,1.,1.),new Line2D.Double(x,y,x+40,y+slope),2.);call(b,"setGrade",Double.valueOf(grade));call(b,"setContextualGrade",Double.valueOf(.99));call(b,"setId",serial++);cases.add(observe(List.of(ledgerSection(1,200,200,16,1)),List.of(b)));
  }
  Object source=call(call(sheet,"getPicture"),"getSource",Class.forName("org.audiveris.omr.sheet.Picture$SourceKey").getField("NO_STAFF").get(null));Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"interline\":"+il+",\"fore\":"+fore+",\"good_grade\":"+good+",\"no_staff\":"+StemSeedsProbe.mask(source)+",\"real_systems\":["+String.join(",",realCases)+"],\"cases\":["+String.join(",",cases)+"],\"scope\":\"Untouched original BEAMS on real Laura, original LedgersFilter purge, intrinsic good-full-beam predicate and original getCandidateFilaments. No ledger acceptance or registration.\"}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
